import clsx from 'clsx';
import React, { ChangeEvent, forwardRef, useEffect, useRef } from 'react';

import { CheckmarkSmallIcon, MinusIcon } from '@dynatrace/strato-icons';

import {
  checkboxIconCSS,
  checkboxKnobCSS,
  checkboxLabelCSS,
} from './Checkbox.sty.js';
import { _VisuallyHidden as VisuallyHidden } from '../../core/components/visually-hidden/VisuallyHidden.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useFormControlState } from '../../core/hooks/useFormControlState.js';
import { _useId } from '../../core/hooks/useId.js';
import { _useSafeForwardProps } from '../../core/hooks/useSafeForwardProps.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import { FocusEvents } from '../../core/types/events.js';
import { FormControlStateProps } from '../../core/types/form-control-state.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';
import { Hint } from '../forms-core/components/hint/Hint.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import { FormFieldAction } from '../forms-core/state/formfield-state-reducer.js';
import { _useInputHint } from '../hooks/useInputHint.js';

// #region Typings
/** Properties for the checkbox component */
export interface CheckboxBaseProps
  extends WithChildren,
    DOMProps,
    AriaLabelingProps,
    FormControlStateProps,
    FocusEvents,
    StylingProps,
    DataTestId {
  /**
   * A string representing the value used for the checkbox.
   * When submitted in a form, it is only submitted if checked, with the set value.
   * If undefined, the string 'on' is submitted by default as per https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/checkbox#attr-value.
   */
  formValue?: string;
  /**
   * Whether the checkbox is disabled.
   * If true, the checkbox cannot be interacted with and is not submitted in a form.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether the checkbox is required or not.
   * @defaultValue false
   */
  required?: boolean;
}

export interface CheckboxUncontrolledProps {
  /** Whether the (uncontrolled) checkbox is checked by default or not. */
  defaultValue?: boolean | 'indeterminate';
  /**
   * The name used for the checkbox.
   * This is submitted along with the value when the form data is submitted.
   * If the name is undefined or empty, the input's value is not submitted with the form.
   */
  name: string;
  /**
   * Whether the checkbox is checked or not.
   * If present, it indicates that the checkbox is checked by default (when the page loads).
   * If false, the checkbox is not submitted in a form.
   */
  value?: never;
  /** Handler that is called when the checked attribute changes. */
  onChange?: never;
}

export interface CheckboxControlledProps {
  /**
   * Whether the checkbox is checked or not.
   * If present, it indicates that the checkbox is checked by default (when the page loads).
   * If false, the checkbox is not submitted in a form.
   */
  value: boolean | 'indeterminate';
  /**
   * The name used for the checkbox.
   * This is submitted along with the value when the form data is submitted.
   * If the name is undefined or empty, the input's value is not submitted with the form.
   */
  name?: string;
  /** Handler that is called when the checked attribute changes. */
  onChange: (checked: boolean, event?: ChangeEvent<HTMLInputElement>) => void;
  /** The default checked or unchecked state. */
  defaultValue?: never;
}

export type CheckboxProps = CheckboxBaseProps &
  (CheckboxControlledProps | CheckboxUncontrolledProps);
// #endregion

/**
 * Checkboxes allow the user to select one or more options from a list of options.
 */
export const Checkbox = forwardRef<HTMLLabelElement, CheckboxProps>(
  (props, forwardedRef) => {
    const {
      disabled: propDisabled,
      required: propRequired,
      id: propId,
      defaultValue,
      value,
      name,
      formValue,
      onChange,
      children,
      controlState,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: CheckboxProps = props;

    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);
    const forwardProps = _useSafeForwardProps(
      remainingProps,
      ariaLabelingProps,
    );

    const inputRef = useRef<HTMLInputElement>(null);

    const [state, setState] = _useControllableState({
      defaultValue,
      value,
    });

    const {
      controlId,
      required: contextRequired,
      disabled: contextDisabled,
      dispatch,
    } = _useFormFieldContext();

    if (
      (propId !== undefined && propId !== controlId) ||
      (propDisabled !== undefined && propDisabled !== contextDisabled) ||
      (propRequired !== undefined && propRequired !== contextRequired)
    ) {
      dispatch?.({
        type: FormFieldAction.UPDATE,
        payload: {
          id: propId,
          disabled: propDisabled,
          required: propRequired,
        },
      });
    }

    const generatedUniqueId = _useId();
    const id = propId || controlId || generatedUniqueId;
    const disabled = propDisabled || contextDisabled;
    const required = propRequired || contextRequired;

    const [hasError, hint] = _useFormControlState(controlState);
    const { containerProps, inputProps, hintProps } = _useInputHint({
      hint,
      hasError,
    });

    const { focusProps, focusClassName } = useFocusRing({
      variant: hasError
        ? 'critical'
        : !disabled && state
        ? 'primary'
        : 'neutral',
    });

    const handleOnChange = (e: ChangeEvent<HTMLInputElement>): void => {
      const newValue = e.target.indeterminate ? true : e.target.checked;
      setState(newValue);
      onChange?.(newValue, e);
    };

    useEffect(() => {
      if (inputRef.current) {
        inputRef.current.indeterminate = value === 'indeterminate';
      }
    }, [value]);

    return (
      <Flex
        data-testid={dataTestId}
        flexDirection="column"
        gap={4}
        className={consumerClassName}
        style={consumerStyle}
        {..._mergeProps(forwardProps, containerProps)}
      >
        <label
          ref={forwardedRef}
          data-testid="checkbox-label"
          htmlFor={id}
          className={clsx(
            checkboxLabelCSS({
              required: typeof children === 'string' && required,
              disabled,
            }),
            textStyleCSS({ fontStyle: 'text', textStyle: 'base' }),
          )}
        >
          <div
            data-testid="checkbox-knob"
            className={clsx(
              checkboxKnobCSS({
                disabled,
                hasChildren: !!children,
                hasError,
                checked: state === true || state === 'indeterminate',
              }),
              focusClassName,
            )}
          >
            <VisuallyHidden>
              <input
                id={id}
                type="checkbox"
                aria-checked={state === 'indeterminate' ? 'mixed' : state}
                aria-required={required}
                data-testid="checkbox-input"
                name={name}
                value={formValue}
                disabled={disabled}
                required={required}
                checked={state === true}
                onChange={handleOnChange}
                ref={inputRef}
                {..._mergeProps(focusProps, ariaLabelingProps, inputProps)}
              />
            </VisuallyHidden>
            <div className={checkboxIconCSS({ disabled, hasError })}>
              <CheckboxIconSvg state={state} />
            </div>
          </div>
          {children}
        </label>
        <Hint hasError={hasError} disabled={disabled} {...hintProps}>
          {hint}
        </Hint>
      </Flex>
    );
  },
);
(Checkbox as typeof Checkbox & { displayName: string }).displayName =
  'Checkbox';

type CheckboxIconProps = {
  state: boolean | 'indeterminate';
};

/** Determines what svg to display based on the checked and indeterminate attributes. */
const CheckboxIconSvg = (props: CheckboxIconProps) => {
  switch (props.state) {
    case true:
      return <CheckmarkSmallIcon />;
    case 'indeterminate':
      return <MinusIcon />;
    case false:
    default:
      return null;
  }
};
